const RoleTyping = () => {
  const [roleIndex, setRoleIndex] = useState(0);
  const [characterCount, setCharacterCount] = useState(0);
  const [phase, setPhase] = useState("typing");
  const [reduceMotion, setReduceMotion] = useState(false);
  const currentRole = roles[roleIndex];

  useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    const updatePreference = () => setReduceMotion(mediaQuery.matches);
    updatePreference();
    if (mediaQuery.addEventListener) mediaQuery.addEventListener("change", updatePreference);
    else mediaQuery.addListener(updatePreference);
    return () => {
      if (mediaQuery.removeEventListener) mediaQuery.removeEventListener("change", updatePreference);
      else mediaQuery.removeListener(updatePreference);
    };
  }, []);

  useEffect(() => {
    if (reduceMotion) return undefined;

    const delay = phase === "pause" ? 1350 : phase === "deleting" ? 38 : 78;
    const timer = window.setTimeout(() => {
      if (phase === "typing") {
        if (characterCount < currentRole.length) setCharacterCount(characterCount + 1);
        else setPhase("pause");
      } else if (phase === "pause") {
        setPhase("deleting");
      } else if (characterCount > 0) {
        setCharacterCount(characterCount - 1);
      } else {
        setRoleIndex((roleIndex + 1) % roles.length);
        setPhase("typing");
      }
    }, delay);

    return () => window.clearTimeout(timer);
  }, [characterCount, currentRole, phase, reduceMotion, roleIndex]);

  return (
    <>
      <span className={styles.roleTyping} aria-hidden="true">
        {reduceMotion ? roles[0] : currentRole.slice(0, characterCount)}
        {!reduceMotion && <span className={styles.typingCursor} />}
      </span>
      <span className={styles.visuallyHidden}>
        UI/UX Designer, UI/UX Developer, Frontend Developer, and Photographer
      </span>
    </>
  );
};

